// Normalisera SCB JSON-stat2 → smal form för Supabase
// Hanterar godtyckligt antal dimensioner (Region, Kon, SNI2007, Tid, etc.)

const data = $input.first().json;

const ids = data.id;
const sizes = data.size;
const dims = data.dimension;
const values = data.value;

const dimCodes = ids.map(dimId => {
  const cat = dims[dimId].category.index;
  return Object.keys(cat).sort((a, b) => cat[a] - cat[b]);
});

const total = sizes.reduce((a, b) => a * b, 1);
const rows = [];

for (let flatIdx = 0; flatIdx < total; flatIdx++) {
  if (values[flatIdx] === null || values[flatIdx] === undefined) continue;

  let remainder = flatIdx;
  const coords = new Array(sizes.length);
  for (let i = sizes.length - 1; i >= 0; i--) {
    coords[i] = remainder % sizes[i];
    remainder = Math.floor(remainder / sizes[i]);
  }

  const row = {};
  ids.forEach((dimId, i) => { row[dimId] = dimCodes[i][coords[i]]; });
  row.value = values[flatIdx];
  rows.push(row);
}

const kommunNamn = {
  "1401":"Härryda","1402":"Partille","1407":"Öckerö","1415":"Stenungsund","1419":"Tjörn",
  "1421":"Orust","1427":"Sotenäs","1430":"Munkedal","1435":"Tanum","1438":"Dals-Ed",
  "1439":"Färgelanda","1440":"Ale","1441":"Lerum","1442":"Vårgårda","1443":"Bollebygd",
  "1444":"Grästorp","1445":"Essunga","1446":"Karlsborg","1447":"Gullspång","1452":"Tranemo",
  "1460":"Bengtsfors","1461":"Mellerud","1462":"Lilla Edet","1463":"Mark","1465":"Svenljunga",
  "1466":"Herrljunga","1470":"Vara","1471":"Götene","1472":"Tibro","1473":"Töreboda",
  "1480":"Göteborg","1481":"Mölndal","1482":"Kungälv","1484":"Lysekil","1485":"Uddevalla",
  "1486":"Strömstad","1487":"Vänersborg","1488":"Trollhättan","1489":"Alingsås","1490":"Borås",
  "1491":"Ulricehamn","1492":"Åmål","1493":"Mariestad","1494":"Lidköping","1495":"Skara",
  "1496":"Skövde","1497":"Hjo","1498":"Tidaholm","1499":"Falköping"
};

const konLabel = { "1": "man", "2": "kvinna", "1+2": "totalt" };

const output = rows.map(r => ({
  json: {
    kommun_kod:  r.Region,
    kommun_namn: kommunNamn[r.Region] || r.Region,
    kpi:         "sysselsatta_naringsgren",
    bransch:     r.SNI2007 || "alla",
    kon:         konLabel[r.Kon] || r.Kon || "totalt",
    ar:          parseInt(r.Tid, 10),
    manad:       null,
    varde:       r.value,
    enhet:       "antal",
    kalla:       "SCB"
  }
}));

return output;

// Normalisera generisk SCB JSON-stat2 (Region + Tid dimensioner)
const raw = $input.first().json;
const data = raw.body ? JSON.parse(raw.body) : raw;

const geografi = {
  "1401":"Härryda","1402":"Partille","1407":"Öckerö","1415":"Stenungsund",
  "1419":"Tjörn","1421":"Orust","1427":"Sotenäs","1430":"Munkedal",
  "1435":"Tanum","1438":"Dals-Ed","1439":"Färgelanda","1440":"Ale",
  "1441":"Lerum","1442":"Vårgårda","1443":"Bollebygd","1444":"Grästorp",
  "1445":"Essunga","1446":"Karlsborg","1447":"Gullspång","1452":"Tranemo",
  "1460":"Bengtsfors","1461":"Mellerud","1462":"Lilla Edet","1463":"Mark",
  "1465":"Svenljunga","1466":"Herrljunga","1470":"Vara","1471":"Götene",
  "1472":"Tibro","1473":"Töreboda","1480":"Göteborg","1481":"Mölndal",
  "1482":"Kungälv","1484":"Lysekil","1485":"Uddevalla","1486":"Strömstad",
  "1487":"Vänersborg","1488":"Trollhättan","1489":"Alingsås","1490":"Borås",
  "1491":"Ulricehamn","1492":"Åmål","1493":"Mariestad","1494":"Lidköping",
  "1495":"Skara","1496":"Skövde","1497":"Hjo","1498":"Tidaholm","1499":"Falköping",
  "01":"Stockholms län","03":"Uppsala län","04":"Södermanlands län",
  "05":"Östergötlands län","06":"Jönköpings län","07":"Kronobergs län",
  "08":"Kalmar län","09":"Gotlands län","10":"Blekinge län",
  "12":"Skåne län","13":"Hallands län","14":"Västra Götalands län",
  "17":"Värmlands län","18":"Örebro län","19":"Västmanlands län",
  "20":"Dalarnas län","21":"Gävleborgs län","22":"Västernorrlands län",
  "23":"Jämtlands län","24":"Västerbottens län","25":"Norrbottens län"
};

const indikator = $('Loop Over Items').first().json;
const kpi   = indikator.kpi;
const enhet = indikator.enhet;
const kalla = indikator.kalla;

const dimIds     = data.id;
const sizes      = data.size;
const dimensions = data.dimension;
const values     = data.value;

function getSortedCodes(dimId) {
  const cat = dimensions[dimId].category;
  const idx = cat.index;
  return Object.keys(idx).sort((a, b) => idx[a] - idx[b]);
}

const regionCodes = getSortedCodes("Region");
const tidCodes    = getSortedCodes("Tid");
const tidCount    = tidCodes.length;
const regionCount = regionCodes.length;

const regionPos = dimIds.indexOf("Region");
const tidPos    = dimIds.indexOf("Tid");

function getStride(pos) {
  let stride = 1;
  for (let i = pos + 1; i < dimIds.length; i++) stride *= sizes[i];
  return stride;
}
const regionStride = getStride(regionPos);
const tidStride    = getStride(tidPos);

const rows = [];
for (let ri = 0; ri < regionCount; ri++) {
  for (let ti = 0; ti < tidCount; ti++) {
    const flatIdx = ri * regionStride + ti * tidStride;
    const varde   = values[flatIdx];
    if (varde === null || varde === undefined) continue;
    rows.push({
      json: {
        kommun_kod:  regionCodes[ri],
        kommun_namn: geografi[regionCodes[ri]] || regionCodes[ri],
        ar:          parseInt(tidCodes[ti], 10),
        kalla:       kalla,
        kpi:         kpi,
        bransch:     "alla",
        kon:         "totalt",
        varde:       varde,
        enhet:       enhet
      }
    });
  }
}
return rows;

// Normalisera Kolada-svar — behåll ALLA år (inte bara senaste)
