  "1487":"Vänersborg","1488":"Trollhättan","1489":"Alingsås","1490":"Borås",
  "1491":"Ulricehamn","1492":"Åmål","1493":"Mariestad","1494":"Lidköping",
  "1495":"Skara","1496":"Skövde","1497":"Hjo","1498":"Tidaholm","1499":"Falköping"
};

const indikator = $('Loop Over Items').first().json;
const kpi   = indikator.kpi;
const enhet = indikator.enhet;
const kalla = indikator.kalla;

const rows = [];
for (const item of values) {
  const munId  = item.municipality;
  const period = item.period;
  const genderValues = item.values || [];
  const totalt = genderValues.find(v => v.gender === "T") || genderValues[0];
  const varde = totalt?.value;
  if (varde === null || varde === undefined) continue;
  rows.push({
    json: {
      kommun_kod:  munId,
      kommun_namn: kommunNamn[munId] || munId,
      ar:          parseInt(period, 10),
      manad:       null,
      kalla:       kalla,
      kpi:         kpi,
      bransch:     "alla",
      kon:         "totalt",
      varde:       varde,
      enhet:       enhet
    }
  });
}
return rows;

// Normalisera AF-svar från scb-mcp-v2 /af-endpoint
const raw = $input.first().json;

if (raw.error) {
  throw new Error(`AF-endpoint fel: ${raw.error}`);
}

const values = raw.values || [];

if (values.length === 0) {
  return [];
}

const indikator = $('Loop Over Items').first().json;
const kpi   = indikator.kpi;
const enhet = indikator.enhet || 'procent';
const kalla = indikator.kalla || 'AF';

return values
  .filter(v => v.value !== null && v.value !== undefined)
  .map(v => ({
    json: {
      kommun_kod:  v.kommun_kod,
      kommun_namn: v.kommun_namn,
      ar:          parseInt((v.period || '0').split('-')[0], 10),
      manad:       v.period || null,
      kalla:       kalla,
      kpi:         kpi,
      bransch:     'alla',
      kon:         'totalt',
      varde:       v.value,
      enhet:       enhet
    }
  }));

const item = $input.first().json;
const now  = new Date().toISOString();

const felInfo = {
  tidpunkt:   now,
  nod:        item.node?.name || item.execution?.lastNodeExecuted || 'okänd nod',
  fel:        item.error?.message || item.message || JSON.stringify(item).slice(0, 300),
  indikator:  $('Loop Over Items').first()?.json?.kpi || 'okänd'
};

console.error('VG Dashboard fel:', JSON.stringify(felInfo));

return [{ json: felInfo }];

